/*
 * Post-build step for index.html (runs after build-html.js and Tailwind).
 *
 * 1. Every local stylesheet and inline <style> in <head> is concatenated in
 *    its original cascade order into dist/site.min.css (minified). Nothing is
 *    reordered, so the cascade is the same as loading the files one by one.
 * 2. src/critical.css (above-the-fold rules, generated by build-critical.js)
 *    is inlined where the first stylesheet was, and the full file loads
 *    without blocking render (media="print" swap, <noscript> fallback). The
 *    full file re-declares every critical rule in the same order, so once it
 *    applies the result is identical to today.
 * 3. The Google Fonts stylesheets load the same non-blocking way (text fonts
 *    use font-display: swap, icons block, both set by Google's CSS).
 * 4. Local scripts are minified into dist/js/ and the <script> tags point
 *    there. Attributes (defer, order) are unchanged.
 *
 * Needs no browser, so it can run anywhere `npm run build` runs.
 */
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const esbuild = require("esbuild");

const htmlPath = "index.html";
const cssOut = "dist/site.min.css";
const jsOutDir = "dist/js";
const criticalPath = "src/critical.css";

const hash = (text) =>
  crypto.createHash("sha256").update(text).digest("hex").slice(0, 10);

// charset utf8: Arabic stays as UTF-8 instead of \uXXXX escapes, which made
// site-i18n.js larger minified than as source.
const CSS_OPTIONS = {
  loader: "css",
  minify: true,
  charset: "utf8",
  // Keep modern syntax (color-mix, :is, logical properties) as written.
  target: ["chrome110", "safari16", "firefox110"],
};

const JS_OPTIONS = {
  loader: "js",
  minify: true,
  charset: "utf8",
  // Classic scripts: top-level names stay global, nothing is bundled.
  target: "es2020",
  legalComments: "none",
};

const localPath = (href) => href.replace(/^\.?\//, "").split("?")[0];
const isLocal = (href) => !/^https?:\/\//.test(href);

let html = fs.readFileSync(htmlPath, "utf8");

const headEnd = html.indexOf("</head>");
if (headEnd === -1) throw new Error("index.html has no </head>");

let head = html.slice(0, headEnd);
const rest = html.slice(headEnd);

/* ------------------------------------------------------------- 1. CSS */

const cssParts = [];
let firstCssIndex = -1;

head = head.replace(
  /<link\b[^>]*\brel="stylesheet"[^>]*>|<style\b[^>]*>[\s\S]*?<\/style>/g,
  (tag, offset) => {
    if (tag.startsWith("<style")) {
      if (firstCssIndex === -1) firstCssIndex = offset;
      cssParts.push({
        source: "inline <style>",
        css: tag.replace(/^<style\b[^>]*>/, "").replace(/<\/style>$/, ""),
      });
      return "";
    }

    const href = (tag.match(/\bhref="([^"]+)"/) || [])[1];
    if (!href || !isLocal(href)) return tag;

    if (firstCssIndex === -1) firstCssIndex = offset;
    cssParts.push({
      source: localPath(href),
      css: fs.readFileSync(localPath(href), "utf8"),
    });
    return "";
  },
);

if (!cssParts.length) throw new Error("No stylesheets found in <head>");

const mergedCss = cssParts
  .map((part) => `/* ${part.source} */\n${part.css}`)
  .join("\n");

const minifiedCss = esbuild.transformSync(mergedCss, CSS_OPTIONS).code;

fs.mkdirSync(path.dirname(cssOut), { recursive: true });
fs.writeFileSync(cssOut, minifiedCss);

// Unminified copy for build-critical.js, which filters it rule by rule.
fs.mkdirSync(".cache", { recursive: true });
fs.writeFileSync(".cache/site.merged.css", mergedCss);
const cssHref = `dist/site.min.css?v=${hash(minifiedCss)}`;

/* ------------------------------------------------- 2. Critical CSS */

const mergedHash = hash(mergedCss);
let criticalTag = "";

if (fs.existsSync(criticalPath)) {
  const critical = fs.readFileSync(criticalPath, "utf8");
  const builtFrom = (critical.match(/built from merged CSS ([0-9a-f]{10})/) ||
    [])[1];

  if (builtFrom !== mergedHash) {
    console.warn(
      `[build-assets] src/critical.css was built from CSS ${builtFrom || "?"}, ` +
        `current CSS is ${mergedHash}. Run \`npm run build:critical\`. ` +
        "The page still renders correctly once the full stylesheet loads.",
    );
  }

  const minifiedCritical = esbuild.transformSync(critical, CSS_OPTIONS).code;

  criticalTag = `<style id="critical-css">${minifiedCritical.trim()}</style>\n`;
}

const asyncStylesheet = (href) =>
  criticalTag
    ? `<link rel="stylesheet" href="${href}" media="print" onload="this.media='all'" />\n` +
      `    <noscript><link rel="stylesheet" href="${href}" /></noscript>`
    : `<link rel="stylesheet" href="${href}" />`;

const cssBlock =
  (criticalTag ? `<link rel="preload" href="${cssHref}" as="style" />\n    ` : "") +
  criticalTag +
  "    " +
  asyncStylesheet(cssHref) +
  "\n";

head = head.slice(0, firstCssIndex) + cssBlock + head.slice(firstCssIndex);

/* ------------------------------------------- 3. Google Fonts, async */

if (criticalTag) {
  head = head.replace(
    /<link\b(?=[^>]*\brel="stylesheet")(?=[^>]*\bhref="(https:\/\/fonts\.googleapis\.com\/[^"]+)")[^>]*>/g,
    (_tag, href) => asyncStylesheet(href),
  );
}

// Collapse the blank lines left where the old <link>/<style> tags were.
head = head.replace(/\n[ \t]*(?:\n[ \t]*)+\n/g, "\n\n");

html = head + rest;

/* ---------------------------------------------------------------- 4. JS */

fs.mkdirSync(jsOutDir, { recursive: true });

html = html.replace(
  /<script\b([^>]*)\bsrc="([^"]+)"([^>]*)><\/script>/g,
  (tag, before, src, after) => {
    if (!isLocal(src)) return tag;

    const file = localPath(src);
    if (!fs.existsSync(file) || !file.startsWith("js/")) return tag;

    const code = esbuild.transformSync(
      fs.readFileSync(file, "utf8"),
      JS_OPTIONS,
    ).code;

    const outName = path.basename(file, ".js") + ".min.js";
    fs.writeFileSync(path.join(jsOutDir, outName), code);

    return `<script${before}src="./${jsOutDir}/${outName}?v=${hash(code)}"${after}></script>`;
  },
);

fs.writeFileSync(htmlPath, html);

const kb = (n) => `${(n / 1024).toFixed(1)}KB`;
console.log(
  `[build-assets] ${cssParts.length} stylesheets -> ${cssOut} ` +
    `(${kb(Buffer.byteLength(mergedCss))} -> ${kb(Buffer.byteLength(minifiedCss))})` +
    (criticalTag ? `, critical ${kb(Buffer.byteLength(criticalTag))} inline` : ", no critical CSS"),
);
